/**
 * Primary diagnosis. Kind-specific fields vary by diagnosis kind;
 * `kind` is the discriminator and additional properties carry the
 * kind-specific evidence.
 *
 */
export type Diagnosis = {
    kind: string;
    title: string;
    evidence_strength?: string;
    lead?: string;
    interpretation: string;
    next_step: string;
    policy_guidance?: string;
    limitation: string;
    occurrence_id: number;
    host_id?: number;
    /**
     * Exact loaded policy identity evaluated for this occurrence, when available.
     */
    policy_identity?: string;
    /**
     * Host-observed checkpoint timestamp associated with the occurrence; boolean values are checkpoint-scoped, not AVC-time evidence.
     */
    checkpoint_observed_at?: string;
    source_domain?: string;
    /**
     * Process command correlated to the diagnosis occurrence, when retained.
     */
    process_command?: string;
    /**
     * Executable path correlated to the diagnosis occurrence, when retained.
     */
    executable?: string;
    target_type?: string;
    target_class?: string;
    permissions?: Array<string>;
    path?: string;
    /**
     * SELinux type from the AVC tcontext at denial time T1.
     */
    observed_type?: string;
    /**
     * Full AVC tcontext recorded at denial time T1.
     */
    observed_context?: string;
    /**
     * SELinux type resolved by host matchpathcon at inspection time T2.
     */
    expected_type?: string;
    /**
     * Full expected context returned by host matchpathcon at T2.
     */
    expected_context?: string;
    /**
     * Object type supplied to matchpathcon, derived from AVC tclass and checked against PATH mode when available.
     */
    file_type?: string;
    /**
     * Host inspection time T2; it does not establish that the same configuration applied at T1.
     */
    expected_context_observed_at?: string;
    expected_context_resolver?: string;
    observation_event_id?: number;
    operation?: string;
    bind_port?: string | null;
    destination_port?: string | null;
    conditional_rules?: Array<{
        [key: string]: unknown;
    }>;
    condition_boolean_states?: Array<{
        [key: string]: unknown;
    }>;
    booleans?: Array<{
        [key: string]: unknown;
    }>;
    [key: string]: unknown;
};

